<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import QRCode from 'qrcode'
import { Check, Copy, Download, ExternalLink, QrCode, Share2, Smartphone } from 'lucide-vue-next'
import { fetchStocks, getStocks } from '../services/stocks'
import { getAccount } from '../services/auth'
import { fetchSettings } from '../services/settings'

const canvas=ref<HTMLCanvasElement>(),copied=ref(false),account=getAccount(),menuUrl=`${window.location.origin}/menu/${account?.slug||'demo'}`
const allProducts=ref(getStocks()),menuTitle=ref(account?.company||'QR Menü'),menuLogo=ref(''),menuBanner=ref('')
const products=computed(()=>allProducts.value.filter(s=>s.status==='active').slice(0,4))
onMounted(async()=>{try{const [items,settings]=await Promise.all([fetchStocks(),fetchSettings()]);allProducts.value=items;menuTitle.value=settings.menuTitle||settings.company;menuLogo.value=settings.logo||'';menuBanner.value=settings.banner||''}catch{}if(canvas.value)QRCode.toCanvas(canvas.value,menuUrl,{width:220,margin:2,errorCorrectionLevel:'H',color:{dark:'#202522',light:'#ffffff'}})})
function download(){const a=document.createElement('a');a.download='qr-menu-kodu.png';a.href=canvas.value?.toDataURL('image/png')??'';a.click()}
async function copyUrl(){await navigator.clipboard?.writeText(menuUrl);copied.value=true;setTimeout(()=>copied.value=false,1800)}
async function share(){if(navigator.share)await navigator.share({title:'QR Menü',text:'Menümüzü inceleyin',url:menuUrl});else await copyUrl()}
</script>

<template>
<div class="qr-page">
  <header class="qr-head"><div><span>DİJİTAL MENÜ</span><h2>QR menünüz hazır</h2><p>Tek kodla menünüzü masalara taşıyın ve misafirlerinize hızlı erişim sağlayın.</p></div><div class="publish-pill"><i></i><span><b>Menü yayında</b><small>{{products.length}} aktif ürün</small></span></div></header>
  <div class="qr-grid">
    <section class="qr-card">
      <div class="card-head"><div><span class="head-icon"><QrCode :size="20"/></span><div><h3>Menü QR kodu</h3><p>Yazdırın veya dijital olarak paylaşın</p></div></div><span class="live"><i></i>CANLI</span></div>
      <div class="qr-content"><div class="qr-frame"><span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span><canvas ref="canvas"></canvas><div class="qr-logo"><QrCode :size="18"/></div></div><div class="qr-help"><h4>Telefonunuzla tarayın</h4><p>QR kod, menünüzün güncel haline otomatik olarak yönlendirir. Ürün değişikliklerinde yeniden kod oluşturmanız gerekmez.</p><div><span><Check :size="13"/>Sınırsız kullanım</span><span><Check :size="13"/>Anında güncelleme</span></div></div></div>
      <div class="url-box"><div><small>MENÜ BAĞLANTISI</small><strong>{{menuUrl}}</strong></div><button @click="copyUrl"><Check v-if="copied" :size="16"/><Copy v-else :size="16"/>{{copied?'Kopyalandı':'Kopyala'}}</button></div>
      <div class="qr-actions"><button class="download" @click="download"><Download :size="17"/>QR kodu indir</button><button @click="share"><Share2 :size="17"/>Paylaş</button><a :href="menuUrl" target="_blank"><ExternalLink :size="17"/>Menüyü aç</a></div>
      <div class="print-note"><span>İPUCU</span><p>En iyi tarama sonucu için QR kodu en az <b>4 × 4 cm</b> boyutunda yazdırın.</p></div>
    </section>

    <section class="preview-side"><div class="preview-label"><Smartphone :size="16"/><span><b>Canlı önizleme</b><small>Misafirlerinizin göreceği ekran</small></span></div><div class="phone"><div class="phone-speaker"></div><div class="phone-screen"><div class="mobile-cover" :style="menuBanner?{backgroundImage:`linear-gradient(135deg,#24342cdd,#1c241fbb),url(${menuBanner})`,backgroundSize:'cover',backgroundPosition:'center'}:undefined"><div class="menu-logo"><img v-if="menuLogo" :src="menuLogo"/><QrCode v-else :size="20"/></div><small>HOŞ GELDİNİZ</small><h3>{{menuTitle}}</h3><p>Taptaze lezzetleri keşfedin</p></div><div class="mobile-body"><div class="mobile-tabs"><b>Popüler</b><span>Ana yemekler</span><span>İçecekler</span></div><div v-for="(item,index) in products" :key="item.id" class="mobile-item"><div class="item-photo"><img v-if="item.image" :src="item.image" :alt="item.name"/><span v-else>{{index+1}}</span></div><div><strong>{{item.name}}</strong><small>{{item.category}}</small><b>{{item.price.toLocaleString('tr-TR')}} ₺</b></div></div><div v-if="!products.length" class="mobile-empty">Aktif ürün bulunmuyor</div></div></div><div class="phone-home"></div></div><a :href="menuUrl" target="_blank" class="full-preview">Tam ekran önizle <ExternalLink :size="15"/></a></section>
  </div>
</div>
</template>

